import fs from 'node:fs';
import path from 'node:path';
import { digest } from './digest.mjs';
import { findDuplicates, renderDuplicates } from './dupes.mjs';
import { fetchReport } from './fetch.mjs';

// §0.9: a file is generated or hand-written, never both. Generated files carry this header.
export const mdHeader = (by) => `<!-- GENERATED by ${by} — do not edit -->\n`;
export const hashHeader = (by) => `# GENERATED by ${by} — do not edit\n`;

/** Deterministic generated files of a knowledge repo (path → content). Inputs are all in the repo. */
export function regenerate(root) {
  const out = {
    'migration/content-digest.md': mdHeader('kb digest') + digest(root).text,
    'migration/entity-duplicates.md': mdHeader('kb entity-duplicates') + renderDuplicates(findDuplicates(root)),
  };
  if (fs.existsSync(path.join(root, 'migration', 'fetch-log.jsonl'))) out['migration/fetch-report.md'] = mdHeader('kb fetch') + fetchReport(root).text;
  return out;
}

/** Write the generated files, or with check=true list the committed ones that regeneration would change. */
export function regen(root, { check = false } = {}) {
  const changed = [];
  for (const [rel, text] of Object.entries(regenerate(root))) {
    const f = path.join(root, rel);
    const cur = fs.existsSync(f) ? fs.readFileSync(f, 'utf8').replace(/\r\n/g, '\n') : null;
    if (cur === text) continue;
    if (check) { if (cur != null) changed.push(rel); continue; }
    fs.mkdirSync(path.dirname(f), { recursive: true });
    fs.writeFileSync(f, text);
    changed.push(rel);
  }
  return changed;
}
